<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operations Console · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'operations-console',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">PHASES 4–10</p><h1>Operations console</h1><p>Schedule recovery, request controls, urgent coverage, forecasts, queue ownership, and delegated access.</p></div><a class="button primary" href="<?=esc(url_for('command-center'))?>">Command center</a></header><?php if($notice):?><div class="page-flash success"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><?php if($error):?><div class="form-alert error"><?=esc($error)?></div><?php endif;?>
<section class="planning-grid"><article class="panel"><h2>Schedule recovery</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="undo_shift_change"><label>Recent change<select name="history_id"><?php foreach($shiftHistory as $event):if(!$event['before_json'])continue;?><option value="<?=$event['id']?>"><?=esc($event['shift_date'].' · '.$event['action'].' · '.$event['changed_by_name'])?></option><?php endforeach;?></select></label><button class="button secondary">Restore prior state</button></form><hr><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="bulk_edit_shifts"><label>Shifts<select name="shift_ids[]" multiple size="8"><?php foreach($boardShifts as $shift):?><option value="<?=$shift['id']?>"><?=esc($shift['shift_date'].' · '.$shift['department_name'].' · '.date('g:i A',strtotime($shift['starts_at'])))?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">Keep status</option><option value="open">Open</option><option value="assigned">Assigned</option><option value="filled">Filled</option><option value="cancelled">Cancelled</option></select></label><label>Shared note<input name="notes" maxlength="500"></label><button class="button primary">Apply bulk edit</button></form></article>
<article class="panel"><h2>Request policy</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="save_time_off_policy"><label>Name<input name="name" required></label><label>Request type<select name="request_type_id"><option value="">Any</option><?php foreach($requestTypes as $type):?><option value="<?=$type['id']?>"><?=esc($type['name'])?></option><?php endforeach;?></select></label><label>Annual hours<input type="number" name="annual_hours" min="0" step=".25"></label><label>Minimum notice days<input type="number" name="minimum_notice_days" min="0"></label><label>Approval levels<select name="approval_levels"><option>1</option><option>2</option><option>3</option></select></label><button class="button primary">Save policy</button></form><hr><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="add_request_blackout"><label>Name<input name="name" required></label><label>Starts<input type="date" name="starts_on" required></label><label>Ends<input type="date" name="ends_on" required></label><label>Reason<input name="reason"></label><button class="button secondary">Add blackout</button></form><?php foreach($requestControls['blackouts'] as $item):?><div class="planning-row"><span><strong><?=esc($item['name'])?></strong><small><?=esc($item['starts_on'].' to '.$item['ends_on'])?></small></span></div><?php endforeach;?></article>
<article class="panel"><h2>Attendance and escalation</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="record_attendance"><label>Employee<select name="membership_id"><?php foreach($data['people'] as $person):?><option value="<?=$person['membership_id']?>"><?=esc($person['name'])?></option><?php endforeach;?></select></label><label>Event<select name="event_type"><option value="late_arrival">Late arrival</option><option value="early_departure">Early departure</option><option value="callout">Callout</option><option value="no_show">No show</option></select></label><label>Occurred<input type="datetime-local" name="occurred_at" required></label><label>Minutes affected<input type="number" name="minutes_affected" min="0"></label><label>Operational note<input name="notes" maxlength="500"></label><button class="button primary">Record event</button></form><hr><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="create_callout_wave"><label>Open callout<select name="callout_id"><?php foreach($organizationCallouts as $callout):if($callout['status']!=='replacement_open')continue;?><option value="<?=$callout['id']?>"><?=esc($callout['staff_name'].' · '.$callout['shift_date'])?></option><?php endforeach;?></select></label><label>Response deadline, minutes<input type="number" name="response_minutes" min="5" value="30"></label><label>Audience<input name="audience" value="eligible_staff"></label><button class="button secondary">Launch escalation wave</button></form></article>
<article class="panel"><h2>Coverage forecast</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="add_coverage_forecast"><label>Date<input type="date" name="forecast_date" required></label><label>Location<select name="location_id"><?php foreach($data['locations'] as $item):?><option value="<?=$item['id']?>"><?=esc($item['name'])?></option><?php endforeach;?></select></label><label>Department<select name="department_id"><?php foreach($data['departments'] as $item):?><option value="<?=$item['id']?>"><?=esc($item['name'])?></option><?php endforeach;?></select></label><label>Interval start<input type="time" name="starts_at" required></label><label>Interval end<input type="time" name="ends_at" required></label><label>Required staff<input type="number" name="required_count" min="1" value="1"></label><label>Skill mix<input name="required_skill_mix" placeholder="2 MA, 1 RN"></label><label>Float pool<input type="number" name="float_pool_count" min="0"></label><label>Break coverage<input type="number" name="break_coverage_count" min="0"></label><button class="button primary">Add forecast</button></form><?php foreach($coverageForecasts as $forecast):$gap=max(0,(int)$forecast['required_count']-(int)$forecast['assigned_count']);?><div class="planning-row"><span><strong><?=esc($forecast['forecast_date'].' · '.$forecast['department_name'])?></strong><small><?=esc(substr($forecast['starts_at'],0,5).'–'.substr($forecast['ends_at'],0,5).' · '.($forecast['required_skill_mix']?:'Any skill mix'))?></small></span><b class="state-pill <?=$gap?'gap':'covered'?>"><?=$gap?$gap.' short':'Ready'?></b></div><?php endforeach;?></article>
<article class="panel"><h2>Owned command queue</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="create_command_item"><label>Title<input name="title" required></label><label>Type<input name="item_type" value="operational"></label><label>Urgency 0–100<input type="number" name="urgency_score" min="0" max="100" value="50"></label><label>Owner<select name="owner_membership_id"><option value="">Unassigned</option><?php foreach($data['people'] as $person):?><option value="<?=$person['membership_id']?>"><?=esc($person['name'])?></option><?php endforeach;?></select></label><label>Due<input type="datetime-local" name="due_at"></label><button class="button primary">Add queue item</button></form><?php foreach($commandItems as $item):?><form method="post" class="planning-row"><?=Csrf::field()?><input type="hidden" name="action" value="update_command_item"><input type="hidden" name="item_id" value="<?=$item['id']?>"><span><strong><?=esc($item['title'])?></strong><small>Urgency <?=$item['urgency_score']?> · <?=esc($item['owner_name']?:'Unassigned')?><?=$item['due_at']?' · due '.esc($item['due_at']):''?></small></span><input name="notes" placeholder="Resolution note"><button class="button primary" name="mode" value="resolve">Resolve</button><button class="button secondary" name="mode" value="snooze">Snooze</button><input type="hidden" name="hours" value="24"></form><?php endforeach;?></article>
<article class="panel"><h2>Temporary delegation</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="add_access_delegation"><label>Employee<select name="membership_id"><?php foreach($data['people'] as $person):?><option value="<?=$person['membership_id']?>"><?=esc($person['name'])?></option><?php endforeach;?></select></label><label>Capability<select name="capability"><option value="schedule">Schedule</option><option value="approve">Approvals</option><option value="payroll">Payroll</option><option value="credentials">Credentials</option></select></label><label>Starts<input type="datetime-local" name="starts_at" required></label><label>Expires<input type="datetime-local" name="expires_at" required></label><button class="button primary">Grant temporary access</button></form><?php foreach($delegations as $delegation):?><div class="planning-row"><span><strong><?=esc($delegation['staff_name'].' · '.$delegation['capability'])?></strong><small><?=esc($delegation['starts_at'].' to '.$delegation['expires_at'])?></small></span><b class="state-pill <?=(!$delegation['revoked_at']&&strtotime($delegation['expires_at'])>time())?'covered':''?>"><?=strtotime($delegation['expires_at'])>time()?'Active':'Expired'?></b></div><?php endforeach;?></article></section></main></body></html>
